"""End-to-end HLS/DASH tests using real streams generated by ffmpeg."""
import json
import shutil
import subprocess
from pathlib import Path

import pytest

from conftest import wait_for
from opendownloader.core import dash, hls
from opendownloader.core.base import ProtectedContentError
from opendownloader.core.media_engine import probe_media
from opendownloader.core.models import Status

FFMPEG = shutil.which("ffmpeg")
pytestmark = pytest.mark.skipif(not FFMPEG, reason="ffmpeg required")
SRC = ["-f", "lavfi", "-i", "testsrc=duration=6:size=320x240:rate=25",
       "-f", "lavfi", "-i", "sine=duration=6", "-c:v", "libx264", "-g", "25", "-c:a", "aac", "-shortest"]


def _serve_dir(files, d: Path, prefix: str):
    for p in d.rglob("*"):
        if p.is_file():
            t = "application/vnd.apple.mpegurl" if p.suffix == ".m3u8" else (
                "application/dash+xml" if p.suffix == ".mpd" else "video/mp2t")
            files[f"{prefix}/{p.relative_to(d).as_posix()}"] = (p.read_bytes(), {"type": t})


def _duration(path: Path) -> float:
    out = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "json", str(path)],
                         capture_output=True, text=True).stdout
    return float(json.loads(out)["format"]["duration"])


def _streams(path: Path) -> set:
    out = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "stream=codec_type", "-of", "json", str(path)],
                         capture_output=True, text=True).stdout
    return {s["codec_type"] for s in json.loads(out)["streams"]}


def test_hls_aes128_master(server, manager, tmp_path):
    base, files = server
    d = tmp_path / "hls"
    d.mkdir()
    key = bytes(range(16))
    (d / "k.key").write_bytes(key)
    (d / "keyinfo").write_text(f"{base}/hls/k.key\n{d / 'k.key'}\n")
    subprocess.run([FFMPEG, "-hide_banner", "-loglevel", "error", *SRC, "-hls_time", "2",
                    "-hls_playlist_type", "vod", "-hls_key_info_file", str(d / "keyinfo"),
                    str(d / "low.m3u8")], check=True)
    (d / "master.m3u8").write_text(
        "#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=400000,RESOLUTION=320x240\nlow.m3u8\n")
    _serve_dir(files, d, "/hls")
    info = probe_media(manager.settings, base + "/hls/master.m3u8")
    assert info["kind"] == "hls" and info["options"][0]["height"] == 240
    item = manager.add(base + "/hls/master.m3u8", kind="hls", media=info["options"][0]["media"],
                       filename="My Video.mp4")
    assert wait_for(lambda: item.status in (Status.COMPLETE, Status.ERROR), 60)
    assert item.status == Status.COMPLETE, item.error
    assert item.path.suffix == ".mp4"
    assert abs(_duration(item.path) - 6) < 0.6
    assert _streams(item.path) == {"video", "audio"}


@pytest.mark.parametrize("timeline", ["1", "0"])
def test_dash_separate_audio_video(server, manager, tmp_path, timeline):
    base, files = server
    d = tmp_path / "dash"
    d.mkdir()
    subprocess.run([FFMPEG, "-hide_banner", "-loglevel", "error", *SRC, "-map", "0:v", "-map", "1:a",
                    "-seg_duration", "2", "-use_timeline", timeline, "-use_template", "1",
                    "-f", "dash", "manifest.mpd"], check=True, cwd=d)
    _serve_dir(files, d, "/dash")
    info = probe_media(manager.settings, base + "/dash/manifest.mpd")
    assert info["kind"] == "dash", info
    video_opts = [o for o in info["options"] if not o.get("audio_only")]
    assert video_opts and video_opts[0]["height"] == 240
    item = manager.add(base + "/dash/manifest.mpd", kind="dash", media=video_opts[0]["media"],
                       filename="dash.mp4")
    assert wait_for(lambda: item.status in (Status.COMPLETE, Status.ERROR), 60)
    assert item.status == Status.COMPLETE, item.error
    assert _streams(item.path) == {"video", "audio"}
    assert abs(_duration(item.path) - 6) < 0.6


def test_drm_is_refused():
    text = ('#EXTM3U\n#EXT-X-KEY:METHOD=SAMPLE-AES,URI="skd://x",KEYFORMAT="com.apple.streamingkeydelivery"\n'
            '#EXTINF:2,\na.ts\n#EXT-X-ENDLIST\n')
    with pytest.raises(ProtectedContentError):
        hls.parse_media(text, "https://x/")
    mpd = """<MPD xmlns="urn:mpeg:dash:schema:mpd:2011" type="static" mediaPresentationDuration="PT4S">
    <Period><AdaptationSet mimeType="video/mp4"><ContentProtection schemeIdUri="urn:uuid:edef8ba9-79d6-4ace-a3c8-27dcd51d21ed"/>
    <Representation id="v" bandwidth="1" width="1" height="1"><SegmentTemplate media="$Number$.m4s" initialization="i.mp4" duration="2" timescale="1"/></Representation>
    </AdaptationSet></Period></MPD>"""
    m = dash.parse_mpd(mpd, "https://x/a.mpd")
    with pytest.raises(ProtectedContentError):
        dash.select(m, None, None)


def test_dash_template_number_format():
    assert dash.fill_template("seg-$RepresentationID$-$Number%05d$.m4s", "v1", number=7) == "seg-v1-00007.m4s"
    assert dash.parse_duration("PT1H2M3.5S") == 3723.5
